import java.util.*;

class Solution {
    public int josephus(int n, int k) {
        Queue<Integer> queue = new LinkedList<>();

        for (int person = 1; person <= n; person++) {
            queue.offer(person);
        }

        while (queue.size() > 1) {
            for (int count = 1; count < k; count++) {
                queue.offer(queue.poll());
            }
            queue.poll();
        }

        return queue.peek();
    }
}
